    for (int i = 0; i < 16; ++i) if (c0 + i < B) o[(size_t)(c0 + i) * kD] = __uint_as_float(r[i]) + bv; }
  asm volatile("tcgen05.fence::before_thread_sync;"); cluster_sync();
  if (warp == 3) { asm volatile("tcgen05.fence::after_thread_sync;"); asm volatile("tcgen05.dealloc.cta_group::2.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(tmem_cols)); }
}
}
extern "C" void get_cyc(long long* h){ cudaMemcpyFromSymbol(h, g_cyc, sizeof(long long)*160); }
extern "C" int run_pair(const float* emb, const float* W, const float* bias, float** outs, int B, int kbs, int flags, cudaStream_t stream) {
  const int Bpad = (B + 15) / 16 * 16; const int tmem_cols = Bpad <= 32 ? 32 : Bpad <= 64 ? 64 : Bpad <= 128 ? 128 : 256;
  const int ebrows = Bpad / 2; const int perK = kWBlk + ebrows * 128, avail = kSmemDyn - 1024;
  int stages = avail / (kbs * perK); if (stages > kMaxStages) stages = kMaxStages;
  CUtensorMap mW, mE;
  cuuint64_t dW[3] = {(cuuint64_t)kBK, (cuuint64_t)kN, (cuuint64_t)kKB}, sW[2] = {(cuuint64_t)kD * 4, (cuuint64_t)kBK * 4};
  cuuint32_t bW[3] = {kBK, kRows, (cuuint32_t)kbs}, es[3] = {1, 1, 1};
  if (cuTensorMapEncodeTiled(&mW, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 3, (void*)W, dW, sW, bW, es, CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) return 411;
  cuuint64_t dE[2] = {(cuuint64_t)kD, (cuuint64_t)B}, sE[1] = {(cuuint64_t)kD * 4}; cuuint32_t bE[2] = {kBK, (cuuint32_t)ebrows};
  if (cuTensorMapEncodeTiled(&mE, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 2, (void*)emb, dE, sE, bE, es, CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) return 412;
  static bool a = false; if (!a) { cudaFuncSetAttribute(k_pair, cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemDyn); a = true; }
  OutPtrs op; for (int i = 0; i < 6; ++i) op.p[i] = outs[i];
  cudaLaunchConfig_t cfg = {}; cfg.gridDim = dim3(kN / kRows); cfg.blockDim = dim3(128); cfg.dynamicSmemBytes = stages * kbs * perK + 1024; cfg.stream = stream;
  cudaLaunchAttribute at[1]; at[0].id = cudaLaunchAttributeClusterDimension; at[0].val.clusterDim.x = 2; at[0].val.clusterDim.y = 1; at[0].val.clusterDim.z = 1;
  cfg.attrs = at; cfg.numAttrs = 1;
  cudaLaunchKernelEx(&cfg, k_pair, mW, mE, bias, op, B, Bpad, kbs, stages, tmem_cols, flags);
  return (int)cudaGetLastError();
